import {
  Component,
  h,
  Prop,
  Element,
  Event,
  EventEmitter,
  State,
  Host,
  Watch,
  ComponentInterface,
} from '@stencil/core';
import { RenderField, ValueField } from '../types';
import { Vue2ValueFix } from '@src/framework/decorators';
import { CSSProperties, formatCSSLength } from '@src/shared/dom';
import { InputMirrorWidthObserver } from '../utils';
import { scheduleLowPriorityTask } from '@src/shared/perf/timing';

const prefix = 'value-field__tagged';
const GAP_WIDTH = 4;
const MORE_TAG_BASE_WIDTH = 16;
const MORE_TAG_CHAR_WIDTH = 10;
const MIN_VISIBLE_TAG_COUNT = 1;

/**
 * @part tagItem
 * @part input - The native input element.
 */
@Component({
  tag: 'ks-tagged-value-field',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsTaggedValueField implements ComponentInterface {
  @Element() el!: HTMLKsTaggedValueFieldElement;
  private contentEl?: HTMLDivElement;

  private inputEl?: HTMLInputElement;
  private inputMirrorEl?: HTMLSpanElement;
  private inputWidthObserver?: InputMirrorWidthObserver;

  /** Render value */
  @Prop() @Vue2ValueFix() value: ValueField[] = [];

  /** Whether to collapse when tags overflow. */
  @Prop() tagsEllipsis = false;

  /** Size of the tag. */
  // 与设计师对齐，标签大小只有 lg
  // @Prop() size: ValueFieldInputSize;

  /** Whether to show close button of tags. */
  @Prop() closeable = true;

  /** Whether the fields presenter is disabled. If `true`, interaction is not allowed. */
  @Prop() disabled?: boolean;

  /** The height of the value field. */
  @Prop() valueFieldHeight: string | number | { min?: string | number; max?: string | number } = { max: 112 };

  /**
   * @private
   * The inline-end offset reserved for the suffix area.
   */
  @Prop() suffixOffset = 0;

  /** Whether to enable input. */
  @Prop() enableInput?: boolean;

  /** Placeholder of input. */
  @Prop() placeholder?: string;

  /** Input value. */
  @Prop() inputValue?: string;

  /** Whether the value field element has focus. */
  @Prop() focusElement?: boolean;

  /** Emitted when the close button of tag is clicked. */
  @Event({ bubbles: false, composed: false }) ksTagClose!: EventEmitter<string | number>;

  /** Emitted when the input value is changed. */
  @Event({ bubbles: false, composed: false }) ksInputChange!: EventEmitter<string>;

  /** Emitted when a key is pressed down in the input. */
  @Event({ bubbles: false, composed: false }) ksInputKeyDown!: EventEmitter<KeyboardEvent>;

  get contentStyle() {
    const scrollbarStyle: CSSProperties = {
      paddingInlineEnd: formatCSSLength(this.suffixOffset),
    };
    if (this._wrap && this.enableInput && this.focusElement) {
      scrollbarStyle['flexWrap'] = 'wrap';
    }
    if (typeof this.valueFieldHeight === 'object') {
      scrollbarStyle['minHeight'] = formatCSSLength(this.valueFieldHeight.min);
      scrollbarStyle['maxHeight'] = formatCSSLength(this.valueFieldHeight.max);
    } else {
      scrollbarStyle['height'] = formatCSSLength(this.valueFieldHeight);
    }
    return scrollbarStyle;
  }

  @State() _renderValue: RenderField[] = [];
  @State() _moreCount = 0;
  @State() _wrap = false;

  componentWillLoad(): Promise<void> | void {
    this._currentInputValue = this.inputValue || '';
    this.updateRenderValue(this.value);
  }

  @Watch('value')
  updateRenderValue(value: ValueField[]) {
    if (this.tagsEllipsis) {
      this._renderValue = value.map((field) => {
        if (this._renderValue.find((item) => item.value === field.value)?.collapsed === false) {
          // istanbul ignore next
          return { ...field, collapsed: false };
        } else {
          return { ...field, collapsed: true };
        }
      });
    } else {
      this._renderValue = value;
    }
    this.syncInputWidth();
  }

  private collapsedTagStyle: CSSProperties = {
    opacity: '0',
    height: '0px',
    overflowY: 'hidden',
    pointerEvents: 'none',
    position: 'absolute',
  };

  private getMoreTagWidth(moreCount: number) {
    return moreCount ? MORE_TAG_CHAR_WIDTH * (moreCount.toString().length + 1) + MORE_TAG_BASE_WIDTH + GAP_WIDTH : 0;
  }

  private updateMore() {
    const tags = this.contentEl?.querySelectorAll<HTMLKsTagElement>(`.${prefix}__tag-item`);
    if (!tags?.length) {
      this._moreCount = 0;
      this._wrap = false;
      return;
    }

    const containerWidth =
      (this.contentEl?.offsetWidth ?? 0) - (this.inputMirrorEl?.offsetWidth ?? 0) - this.suffixOffset;
    const tagWidths = this._renderValue.map((_, index) => tags[index]?.scrollWidth ?? 0);

    let visibleCount = 0;
    let visibleWidth = 0;

    for (; visibleCount < tagWidths.length; visibleCount++) {
      const nextWidth = tagWidths[visibleCount];
      if (!nextWidth || visibleWidth + nextWidth > containerWidth) {
        break;
      }
      visibleWidth += nextWidth + GAP_WIDTH;
    }

    if (visibleCount <= MIN_VISIBLE_TAG_COUNT) {
      visibleCount = Math.min(MIN_VISIBLE_TAG_COUNT, this._renderValue.length);
    }

    while (visibleCount >= MIN_VISIBLE_TAG_COUNT) {
      const moreCount = this._renderValue.length - visibleCount;
      const moreWidth = this.getMoreTagWidth(moreCount);
      if (visibleWidth + moreWidth <= containerWidth || visibleCount === MIN_VISIBLE_TAG_COUNT) {
        break;
      }
      visibleWidth -= (tagWidths[visibleCount - 1] ?? 0) + GAP_WIDTH;
      visibleCount--;
    }

    const wrap = visibleCount === MIN_VISIBLE_TAG_COUNT;
    const nextMoreCount = this._renderValue.length - visibleCount;
    const nextRenderValue = this._renderValue.map((item, index) => ({
      ...item,
      collapsed: index >= visibleCount,
    }));

    this._renderValue = nextRenderValue;
    this._moreCount = nextMoreCount;
    this._wrap = wrap;
  }

  @State() _selectionStart = 0;
  @State() _selectionEnd = 0;
  @State() _currentInputValue = '';
  private composition = false;

  private handleInput = (e: Event) => {
    if (this.disabled || !this.inputEl) {
      return;
    }

    const { value } = e.target as HTMLInputElement;
    this._currentInputValue = value;
    this.syncInputWidth(value);

    if (this.composition || (e as InputEvent).isComposing) {
      return;
    }

    this.ksInputChange.emit(value);

    this._selectionStart = this.inputEl.selectionStart || 0;
    this._selectionEnd = this.inputEl.selectionEnd || 0;
  };

  private handleCompositionStart = () => {
    this.composition = true;
    this._currentInputValue = this.inputEl?.value || '';
  };

  private handleCompositionEnd = (event: Event) => {
    this.composition = false;
    this.handleInput(event);
  };

  private syncSelectionFromInput = () => {
    if (!this.inputEl) {
      return;
    }
    this._selectionStart = this.inputEl.selectionStart || 0;
    this._selectionEnd = this.inputEl.selectionEnd || 0;
  };

  private restoreSelection = () => {
    if (!this.inputEl || !this.isEditing() || this.disabled) {
      return;
    }
    this.inputEl.focus();
    this.inputEl.setSelectionRange(this._selectionStart, this._selectionEnd);
  };

  private handleContainerClick = () => {
    this.restoreSelection();
  };

  private handleInputClick = (e: MouseEvent) => {
    this.syncSelectionFromInput();
    if (this.enableInput && this.focusElement) {
      e.stopPropagation();
    }
  };

  private handleInputKeyDown = (event: KeyboardEvent) => {
    this.ksInputKeyDown.emit(event);
  };

  private handleInputFocus = () => {
    this.syncSelectionFromInput();
    this.restoreSelection();
  };

  private setInputRef = (el?: HTMLInputElement) => {
    this.inputEl = el;
  };

  private shouldShowInputText = () => !!this.enableInput && (!!this.focusElement || !!this._currentInputValue);

  private isEditing = () => !!this.enableInput && !!this.focusElement;

  private shouldShowDisplayPlaceholder = () => !this.value.length && !this._currentInputValue && !!this.placeholder;

  private isEmptyTailDisplayState = () => !!this.value.length && !this._currentInputValue && !this.isEditing();

  private shouldOffsetInputText = () => !this.value.length;

  private getInputValue = () => (this.shouldShowInputText() ? this._currentInputValue : '') || '';

  private syncInputWidth(value?: string) {
    scheduleLowPriorityTask(this.el, () => {
      if (this.inputEl) {
        const mirrorText = this.getMirrorText();
        if (!this.composition) {
          this.inputEl.value = this.getInputValue();
        }
        this.inputWidthObserver?.updateMirrorText(mirrorText);
      }
    });
    if (this.inputEl) {
      const mirrorText = this.getMirrorText(value);
      this.inputWidthObserver?.updateMirrorText(mirrorText);
    }
  }

  @Watch('inputValue')
  onInputValueChange() {
    if (!this.composition) {
      this._currentInputValue = this.inputValue || '';
      this.syncInputWidth(this._currentInputValue);
    }
  }

  @Watch('placeholder')
  onPlaceholderChange() {
    this.syncInputWidth();
  }

  componentDidRender(): void {
    if (this.tagsEllipsis) {
      // istanbul ignore next
      requestAnimationFrame(() => {
        this.updateMore();
      });
    }

    // 初始化并观察镜像 span 的尺寸变化
    if (this.inputEl && this.inputMirrorEl && !this.inputWidthObserver) {
      this.inputWidthObserver = new InputMirrorWidthObserver(this.inputEl, this.inputMirrorEl, formatCSSLength);
      this.inputWidthObserver.start();
    }
  }

  render() {
    return (
      <Host class="KsTaggedValueField">
        <div
          ref={(el) => (this.contentEl = el)}
          class={{
            [prefix]: true,
            [`${prefix}--scroll`]: !this.tagsEllipsis,
            [`${prefix}--collapse`]: this.tagsEllipsis,
          }}
          onClick={this.handleContainerClick}
          style={this.contentStyle}
          data-testid="tagged-index-nwrEkZ"
        >
          {this._renderValue.map((item) => {
            const tagElement = (
              <ks-tag
                class={{
                  [`${prefix}__tag-item`]: true,
                }}
                closeable={this.closeable && (item.closeable === undefined ? true : item.closeable)}
                part="tagItem"
                variant={item.status === 'default' ? 'neutral' : item.status}
                onKsClose={() => {
                  this.ksTagClose.emit(item.value);
                }}
                size="lg"
                style={{
                  maxWidth: `calc(100% - ${this.getMoreTagWidth(this._moreCount)}px)`,
                  ...(item.collapsed
                    ? {
                        ...(item.style || {}),
                        ...this.collapsedTagStyle,
                      }
                    : item.style),
                }}
                disabled={item.disabled === undefined ? this.disabled : item.disabled}
                data-testid="tagged-index-ibRy5F"
              >
                <span>{item.label}</span>
              </ks-tag>
            );
            if (item.popover) {
              return <ks-tooltip {...item.popover}>{tagElement}</ks-tooltip>;
            } else {
              return tagElement;
            }
          })}
          {this._moreCount > 0 && (
            <ks-tooltip
              size="lg"
              content={this._renderValue
                .slice(this._renderValue.length - this._moreCount, this._renderValue.length)
                .map((item) => item.label)
                .join(',')}
            >
              <ks-tag size="lg" disabled={this.disabled} closeable={false} class={`${prefix}__more`} part="tagItem">
                {`+${this._moreCount}`}
              </ks-tag>
            </ks-tooltip>
          )}

          <div
            class={{
              [`${prefix}__input`]: true,
              [`${prefix}__input--absolute`]: this.isEmptyTailDisplayState(),
              [`${prefix}__input--placeholder-offset`]: this.shouldOffsetInputText(),
              [`${prefix}__input--placeholder-visible`]: this.shouldShowDisplayPlaceholder(),
            }}
          >
            <span
              class={{
                [`${prefix}__display-placeholder`]: true,
                [`${prefix}__display-placeholder--hidden`]: !this.shouldShowDisplayPlaceholder(),
                [`${prefix}__display-placeholder--offset`]: this.shouldOffsetInputText(),
              }}
            >
              {this.placeholder}
            </span>
            <input
              ref={this.setInputRef}
              part="input"
              type="text"
              placeholder=""
              disabled={this.disabled}
              value={this.getInputValue()}
              onInput={this.handleInput}
              onCompositionstart={this.handleCompositionStart}
              onCompositionend={this.handleCompositionEnd}
              onClick={this.handleInputClick}
              readOnly={!this.enableInput || !this.focusElement}
              onKeyDown={this.handleInputKeyDown}
              onFocus={this.handleInputFocus}
              data-testid="tagged-index-t3F5Ux"
            />
            <span ref={(el) => (this.inputMirrorEl = el || undefined)} class={`${prefix}__input-mirror`}>
              {this.getMirrorText()}
            </span>
          </div>
        </div>
      </Host>
    );
  }

  private getMirrorText = (value?: string): string => {
    const mergedValue = value === undefined ? this._currentInputValue : value;
    return mergedValue || '\u00A0';
  };
  disconnectedCallback() {
    this.inputWidthObserver?.stop();
    this.inputWidthObserver = undefined;
  }
}
